  <script>
    function updateProgress(pct, cur, tot, elapsed) {
      var p = Number(pct).toFixed(2);
      document.title = 'Uploading ' + p + '%';
      var el = document.getElementById('progress');
      if (el) el.innerHTML = '( ' + p + '% &mdash; ' + cur + ' / ' + tot + ' )<br><small style="text-transform:capitalize;">Elapsed Time: ' + elapsed + '</small>';
      document.body.style.backgroundImage = 'linear-gradient(to right, rgba(0,223,56,0.18) ' + pct + '%, white ' + pct + '%)';
    }

    function appendStatus(html) {
      var c = document.getElementById('statuses');
      if (c) c.insertAdjacentHTML('beforeend', '<div class="status-line">' + html + '</div>');
    }

    function copyToClipboard(text, btn) {
      var done = function () {
        showToast('Copied to clipboard');
        if (btn) {
          btn.classList.add('copied');
          var orig = btn.textContent;
          btn.textContent = 'Copied!';
          setTimeout(function () { btn.textContent = orig; btn.classList.remove('copied'); }, 1600);
        }
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text); done(); });
      } else {
        fallbackCopy(text);
        done();
      }
    }

    function fallbackCopy(text) {
      var ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(ta);
    }

    function showToast(msg) {
      var t = document.getElementById('toast');
      if (!t) {
        t = document.createElement('div');
        t.id = 'toast';
        t.className = 'toast';
        document.body.appendChild(t);
      }
      t.textContent = msg;
      t.classList.add('show');
      clearTimeout(t._timer);
