function handle_upload() {
  set_time_limit(0);

  $url    = trim($_POST["url"]);
  $name   = sanitize_filename($_POST["name"]);
  $folder = sanitize_folder($_POST["folder"] ?? "");
  $extract   = !empty($_POST["extract"]);
  $wpinstall = !empty($_POST["wpinstall"]);

  if ($name === '' || !filter_var($url, FILTER_VALIDATE_URL)) {
    echo '<div class="status-line" style="color:#df0025;">&#9940; invalid url or filename.</div>';
    echo '<a class="btn" href="?r=' . time() . '">try again</a>';
    return;
  }

  ob_implicit_flush(true);
  while (ob_get_level() > 0) ob_end_flush();
  ob_start();

  $base_url = build_base_url();
  $dest_url = $base_url . '/' . ($folder ? "$folder/" : '') . $name;

  echo "<script>
    document.title = 'Uploading ...';
    document.querySelector('h1').innerHTML += `
      <div style=\"font-size:0;margin-top:3rem;\">
        <small style=\"font-size:1rem;\">
          Transferring <a href='" . htmlspecialchars($url, ENT_QUOTES) . "' target='_blank' rel='noopener'>Origin URL-Address</a>
          as <a href='" . htmlspecialchars($dest_url, ENT_QUOTES) . "' target='_blank' rel='noopener'><strong>" . htmlspecialchars(($folder ? "$folder/" : '') . $name, ENT_QUOTES) . "</strong></a>
          <span style=\"margin-top:1rem;display:block;\">Please wait until process completes or press ESC to cancel</span>
        </small>
      </div>
      <div id=\"progress\"></div>
      <div id=\"statuses\"></div>`;
  </script>";
  flush_buffers(true);

  $start_time = microtime(true);
  $root_dir   = __DIR__;
  $dest_dir   = $folder !== '' ? $root_dir . '/' . $folder : $root_dir;
  if (!is_dir($dest_dir)) @mkdir($dest_dir, 0755, true);
  $path_full = rtrim($dest_dir, '/\\') . '/' . $name;
  if (file_exists($path_full)) @unlink($path_full);

  $download_result = download_with_curl($url, $path_full, $start_time);

  if (!$download_result['ok']) {
    echo "<script>appendStatus('&#9940; download failed: " . js_escape($download_result['error']) . "');</script>";
    flush_buffers(true);
    render_completion_buttons($path_full);
    return;
  }

  $filesize = filesize($path_full);
  echo "<script>
    document.title = 'Transferring done!';
    document.querySelector('#progress').innerHTML = '( 100.00% &mdash; " . human_filesize($filesize) . " / " . human_filesize($filesize) . " )';
    document.body.style.backgroundImage = 'linear-gradient(to right, rgba(0,223,56,0.18) 100%, white 100%)';
    appendStatus('&#9989; transfer completed in " . human_timing($start_time) . " &mdash; " . human_filesize($filesize) . "');
  </script>";
  flush_buffers(true);

  if ($wpinstall) {
    run_wordpress_installer($path_full, $root_dir);
  } elseif ($extract) {
    run_archive_extraction($path_full, $dest_dir);
  }

  render_result_urls($url, $dest_url);
  render_completion_buttons($path_full);
}

function download_with_curl($url, $dest_path, $start_time) {
  $fp = fopen($dest_path, 'wb');
  if (!$fp) return ['ok' => false, 'error' => "cannot open destination file for writing"];

  $ch = curl_init($url);
  if (!$ch) { fclose($fp); return ['ok' => false, 'error' => "curl init failed"]; }

  $last_update = 0.0;
  $last_pad    = microtime(true);

  curl_setopt_array($ch, [
    CURLOPT_FILE            => $fp,
    CURLOPT_FOLLOWLOCATION  => true,
    CURLOPT_MAXREDIRS       => 10,
    CURLOPT_SSL_VERIFYHOST  => 0,
    CURLOPT_SSL_VERIFYPEER  => 0,
    CURLOPT_BUFFERSIZE      => 65536,
    CURLOPT_NOPROGRESS      => false,
    CURLOPT_USERAGENT       => 'Mozilla/5.0 (compatible; UploadFromURL/18.0; +https://amirhp.com/)',
    CURLOPT_TIMEOUT         => 0,
    CURLOPT_CONNECTTIMEOUT  => 30,
    CURLOPT_FAILONERROR     => false,
    CURLOPT_PROGRESSFUNCTION => function () use (&$last_update, &$last_pad, $start_time) {
      $args = func_get_args();
      $dl_total = isset($args[1]) ? (float)$args[1] : 0;
      $dl_now   = isset($args[2]) ? (float)$args[2] : 0;
      if ($dl_total < 1) return 0;
      $now = microtime(true);
      $is_done = ($dl_now >= $dl_total);
      if (($now - $last_update) < 0.2 && !$is_done) return 0;
      $last_update = $now;
      $pct = min(100, ($dl_now / $dl_total) * 100);
      $cur = human_filesize($dl_now);
      $tot = human_filesize($dl_total);
      $elapsed = human_timing($start_time);
      echo "<script>updateProgress($pct, '$cur', '$tot', '$elapsed');</script>";
      $pad = ($now - $last_pad) >= 8;
      if ($pad) $last_pad = $now;
      flush_buffers($pad);
      return 0;
    },
  ]);

  $ok      = curl_exec($ch);
  $http    = curl_getinfo($ch, CURLINFO_HTTP_CODE);
  $err     = curl_error($ch);
  curl_close($ch);
  fclose($fp);

  if (!$ok || ($http >= 400 && $http !== 0)) {
    return ['ok' => false, 'error' => "http $http " . ($err ?: '(no curl error)')];
  }
  $size = @filesize($dest_path);
  if ($size === false || $size < 1) {
    return ['ok' => false, 'error' => "downloaded file is empty"];
  }
  return ['ok' => true];
}

function run_archive_extraction($file, $dest_dir) {
  echo "<script>appendStatus('&#9203; extracting archive ...');</script>";
  flush_buffers(true);
  $res = extract_archive($file, $dest_dir);
  if ($res['ok']) {
    echo "<script>appendStatus('&#9989; " . js_escape($res['msg']) . "');</script>";
  } else {
    echo "<script>appendStatus('&#9940; " . js_escape($res['msg']) . "');</script>";
  }
  flush_buffers(true);
}

function run_wordpress_installer($zip_file, $root_dir) {
  echo "<script>appendStatus('&#9203; extracting wordpress archive ...');</script>";
  flush_buffers(true);

  $temp = $root_dir . '/__wp_temp_' . substr(md5(uniqid('', true)), 0, 8);
  if (!@mkdir($temp, 0755, true)) {
    echo "<script>appendStatus('&#9940; cannot create temp folder');</script>";
    flush_buffers(true);
    return;
  }

  $zip = new ZipArchive;
  if ($zip->open($zip_file) !== true) {
    rmdir_recursive($temp);
    echo "<script>appendStatus('&#9940; failed to open wordpress zip');</script>";
    flush_buffers(true);
    return;
  }
  $zip->extractTo($temp);
  $zip->close();
  echo "<script>appendStatus('&#9989; wordpress archive extracted');</script>";
  flush_buffers(true);

  $wp_source = $temp . '/wordpress';
  if (!is_dir($wp_source)) {
    rmdir_recursive($temp);
    echo "<script>appendStatus('&#9940; wordpress/ folder not found inside archive');</script>";
    flush_buffers(true);
    return;
  }

  echo "<script>appendStatus('&#9203; moving wordpress files to root ...');</script>";
  flush_buffers(true);
  $moved_files = 0; $moved_dirs = 0;
  foreach (scandir($wp_source) as $item) {
    if ($item === '.' || $item === '..') continue;
    $src = $wp_source . '/' . $item;
    $dst = $root_dir . '/' . $item;
    if (file_exists($dst)) {
      is_dir($dst) ? rmdir_recursive($dst) : @unlink($dst);
    }
    if (@rename($src, $dst)) {
      is_dir($dst) ? $moved_dirs++ : $moved_files++;
    }
  }
  echo "<script>appendStatus('&#9989; <strong>" . number_format($moved_files) . "</strong> files & <strong>" . number_format($moved_dirs) . "</strong> folders moved to root');</script>";
  flush_buffers(true);

  rmdir_recursive($temp);

  $themes_dir = $root_dir . '/wp-content/themes';
  if (is_dir($themes_dir)) {
    $theme_dirs = [];
    foreach (scandir($themes_dir) as $t) {
      if ($t === '.' || $t === '..') continue;
      if (is_dir($themes_dir . '/' . $t)) $theme_dirs[] = $t;
    }
    sort($theme_dirs, SORT_NATURAL | SORT_FLAG_CASE);
    $latest = end($theme_dirs);
    $removed = 0;
    foreach ($theme_dirs as $t) {
      if ($t === $latest) continue;
      if (rmdir_recursive($themes_dir . '/' . $t)) $removed++;
    }
    if ($latest) {
      echo "<script>appendStatus('&#9989; kept latest theme: <strong>" . js_escape($latest) . "</strong>, removed <strong>$removed</strong> old themes');</script>";
      flush_buffers(true);
    }
  }

  $plugins_dir = $root_dir . '/wp-content/plugins';
  if (is_dir($plugins_dir)) {
    $removed = 0;
    foreach (scandir($plugins_dir) as $p) {
      if ($p === '.' || $p === '..') continue;
      $path = $plugins_dir . '/' . $p;
      if (is_dir($path)) {
        if (rmdir_recursive($path)) $removed++;
      } else {
        if (@unlink($path)) $removed++;
      }
    }
    @file_put_contents($plugins_dir . '/index.php', "<?php\n// Silence is golden.\n");
    echo "<script>appendStatus('&#9989; wiped <strong>$removed</strong> default plugins');</script>";
    flush_buffers(true);
  }

  $robots_path = $root_dir . '/robots.txt';
  $robots_body = "User-agent: *\nDisallow: /\n";
  if (@file_put_contents($robots_path, $robots_body) !== false) {
    echo "<script>appendStatus('&#9989; robots.txt written (block all crawlers)');</script>";
    flush_buffers(true);
  }

  $extras_removed = 0;
  foreach (['license.txt', 'readme.html', 'xmlrpc.php', 'wp-config-sample.php'] as $f) {
    if (@unlink($root_dir . '/' . $f)) $extras_removed++;
  }
  if (@unlink($zip_file)) $extras_removed++;
  echo "<script>appendStatus('&#9989; removed <strong>$extras_removed</strong> extra wordpress files (incl. uploaded zip)');</script>";
  flush_buffers(true);
}

function extract_archive($file, $dest) {
  if (!is_dir($dest)) @mkdir($dest, 0755, true);
  $lower = strtolower($file);

  if (preg_match('/\.zip$/', $lower)) {
    if (!class_exists('ZipArchive')) return ['ok' => false, 'msg' => 'ZipArchive extension not available'];
    $zip = new ZipArchive;
    if ($zip->open($file) !== true) return ['ok' => false, 'msg' => 'failed to open zip archive'];
    $count = $zip->numFiles;
    $zip->extractTo($dest);
    $zip->close();
    return ['ok' => true, 'msg' => "zip extracted ($count entries)"];
  }

  if (preg_match('/\.tar$/', $lower)) {
    if (!class_exists('PharData')) return ['ok' => false, 'msg' => 'PharData extension not available'];
    try {
      $phar = new PharData($file);
      $phar->extractTo($dest, null, true);
      return ['ok' => true, 'msg' => 'tar extracted'];
    } catch (Exception $e) {
      return ['ok' => false, 'msg' => 'tar extract failed: ' . $e->getMessage()];
    }
  }

  if (preg_match('/\.(tar\.gz|tgz)$/', $lower)) {
    if (!class_exists('PharData')) return ['ok' => false, 'msg' => 'PharData extension not available'];
    try {
      $phar = new PharData($file);
      $tar_file = preg_replace('/\.(tar\.gz|tgz)$/', '.tar', $file);
      if (file_exists($tar_file)) @unlink($tar_file);
      $phar->decompress();
      $phar2 = new PharData($tar_file);
      $phar2->extractTo($dest, null, true);
      @unlink($tar_file);
      return ['ok' => true, 'msg' => 'tar.gz extracted'];
    } catch (Exception $e) {
      return ['ok' => false, 'msg' => 'tar.gz extract failed: ' . $e->getMessage()];
    }
  }

  if (preg_match('/\.gz$/', $lower)) {
    if (!function_exists('gzopen')) return ['ok' => false, 'msg' => 'zlib extension not available'];
    $out_file = $dest . '/' . basename($file, '.gz');
    $gz  = @gzopen($file, 'rb');
    $out = @fopen($out_file, 'wb');
    if (!$gz || !$out) {
      if ($gz) gzclose($gz);
      if ($out) fclose($out);
      return ['ok' => false, 'msg' => 'failed to open .gz file'];
    }
    while (!gzeof($gz)) fwrite($out, gzread($gz, 65536));
    gzclose($gz);
    fclose($out);
    return ['ok' => true, 'msg' => 'gz decompressed to ' . basename($out_file)];
  }

  return ['ok' => false, 'msg' => 'unsupported archive format'];
}

