function flush_buffers($pad = false) {
  if ($pad) echo "<!-- " . str_repeat(' ', 4096) . " -->\n";
  while (ob_get_level() > 0) { @ob_end_flush(); }
  @flush();
  ob_start();
}

function js_escape($s) {
  return str_replace(["\\", "'", "\r", "\n", "</"], ["\\\\", "\\'", "", "\\n", "<\\/"], (string)$s);
}

function build_base_url() {
  $proto = (empty($_SERVER['HTTPS']) || $_SERVER['HTTPS'] === 'off') ? 'http' : 'https';
  $host  = $_SERVER['HTTP_HOST'] ?? 'localhost';
  $path  = str_replace('\\', '/', dirname($_SERVER['PHP_SELF'] ?? '/'));
  return rtrim($proto . '://' . $host . $path, '/');
}

function sanitize_filename($name) {
  $name = trim((string)$name);
  $name = str_replace(["\0", '/', '\\'], '', $name);
  $name = preg_replace('/\.\.+/', '.', $name);
  return $name;
}

function sanitize_folder($folder) {
  $folder = trim((string)$folder);
  if ($folder === '') return '';
  $folder = str_replace(["\0", '\\'], ['', '/'], $folder);
  $parts = array_filter(explode('/', $folder), function ($p) {
    return $p !== '' && $p !== '.' && $p !== '..';
  });
  return implode('/', $parts);
}

function get_real_IP_address() {
  if (!empty($_SERVER['GEOIP_ADDR']))            return $_SERVER['GEOIP_ADDR'];
  if (!empty($_SERVER['HTTP_X_REAL_IP']))        return $_SERVER['HTTP_X_REAL_IP'];
  if (!empty($_SERVER['HTTP_CLIENT_IP']))        return $_SERVER['HTTP_CLIENT_IP'];
  if (!empty($_SERVER['HTTP_X_FORWARDED_FOR']))  return explode(',', $_SERVER['HTTP_X_FORWARDED_FOR'])[0];
  return $_SERVER['REMOTE_ADDR'] ?? '(unknown)';
}

function human_filesize($bytes = 0, $decimals = 2) {
  $bytes = (float)$bytes;
  if ($bytes < 1) return '0 B';
  $units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
  $factor = (int) floor(log($bytes, 1024));
  $factor = min($factor, count($units) - 1);
  return sprintf("%.{$decimals}f %s", $bytes / pow(1024, $factor), $units[$factor]);
}

function human_timing($time) {
  $s = microtime(true) - $time;
  $h = (int) floor($s / 3600); $s -= $h * 3600;
  $m = (int) floor($s / 60);   $s -= $m * 60;
  return ($h > 0 ? "$h:" : '') . sprintf('%02d', $m) . ':' . sprintf('%02d', $s);
}

function rmdir_recursive($dir) {
  if (!is_dir($dir)) return false;
  foreach (array_diff(scandir($dir), ['.', '..']) as $file) {
    $path = $dir . '/' . $file;
    is_dir($path) ? rmdir_recursive($path) : @unlink($path);
  }
  return @rmdir($dir);
}

